"""Read-only native GAMEOVER/Config.dat extraction; no original files changed."""
import json,hashlib
from pathlib import Path
from importlib import import_module
e=import_module('extract-lp');n=import_module('native-code').NativeCode();root=Path(__file__).resolve().parent.parent
raw=(e.SOURCE/'Config.dat').read_bytes();stories={}
for kind,offset in [('opening',96),('ending',946)]:
 r=e.Reader(raw,8,start=offset);script=r.string();assert script.startswith('#P 黄')
 stories[kind]={'offset':offset,'bytes':r.pos-offset,'script':script,'sha256':hashlib.sha256(script.encode()).hexdigest()}
assert '#To A00 138 12' in stories['ending']['script'];assert n.string(0x417f08)=='#GAMEOVER'
assert [n.string(a) for a in [0x40e670,0x40e6d0,0x40e724]]==['普通模式','专家模式','地狱模式']
rules={'destination':{'id':'A00','x':138,'y':12},'bossTimers':30,'bossTimerValue':-1,'bossCycleValue':1,'events':30,'eventValue':0,'direction':4,'maxClearCount':32767,'modeUnlockMax':3,'firstClearNotice':1}
data={'source':'Config.dat','sourceSha256':hashlib.sha256(raw).hexdigest(),'rules':rules,**stories}
(root/'public/assets/data/story.json').write_text(json.dumps(data,ensure_ascii=False,separators=(',',':')),encoding='utf8')
files=[]
for name,lo,hi,start in [('dispatch',0x613c20,0x61870c,0x618659),('state',0x62d720,0x62e6cb,0x62e3bd),('page-filter',0x62d720,0x62eadb,0x62e968),('destination',0x62d720,0x62f1f0,0x62eff8)]:
 rows=[r for r in n.disasm(lo,hi) if r[0]>=start];p=root/'reports'/('native-ending-'+name+'.txt');p.write_text('\n'.join(f'{a:08x} {m:8s} {o}' for a,m,o in rows),encoding='utf8');files.append({'file':'reports/'+p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
maps={key:json.loads((root/f'public/assets/maps/{key}.json').read_text(encoding='utf8')) for key in ['A13','A00']};npc=next(x for x in maps['A13']['npcs'] if x['name']=='方丈')
out={'passed':True,'sourceSha256':hashlib.sha256(n.data).hexdigest(),'configSha256':data['sourceSha256'],'dataSha256':hashlib.sha256((root/'public/assets/data/story.json').read_bytes()).hexdigest(),'evidenceFiles':files,'rules':rules,'npc':{'map':'A13','name':'方丈','position':[64,37],'scriptSha256':hashlib.sha256(npc['script'].encode()).hexdigest()},'nativeFields':{'clearCount':'hero word1ff8, increment62e418','modeUnlock':'hero word1fc0, maximum current mode+1 at62e4bf/62e513/62e560','questLog':'hero BSTR1fd0 cleared62e44a','questFlags':'hero words2152..218c zero62e686','events':'hero words218e..21c8 zero62e6ba','bossTimers':'hero dwords21e0..2254=-1 at62e60b','bossCycles':'hero dwords2278..22ec=1 at62e63b','direction':'hero word1f78=4 at62e5cf'},'maps':[{'id':key,'sourceSha256':m['sourceSha256']} for key,m in maps.items()],'nativeBehavior':['GAMEOVER enters native state12 and increases clearCount before displaying ending pages.','Keeps the highest mode unlock: normal1/expert2/hell3; current game mode is not switched.','Clears quest log, all30 quest flags/events and restores all30 boss timers/cycles; no inventory/stat/skill/challenge record reset in this branch.','The last #P white/blue1 page is shown only when the new clearCount equals1.','Ending #To A00 138 12 returns to the village; its load script raises ET0 from0 to3. Fisher/side entrances use clearCount and original ET/mode gates.'],'adaptations':['Portrait native brown panel and original text/primary colors use manual pages instead of the desktop per-character RGB animation; original soft line wraps are reflowed for750x1624.','Per-character settled story checkpoint saves page/return phase. Reload never applies clear-count/reset a second time. Map-load failure keeps a retryable final page.','Reset Web map-flag/NPC mutation caches together with quest arrays so new-cycle gates rebuild from immutable source; map discovery, ground items and following pets keep existing Web persistence.','Ordinary ending works independently of expert/hell entry/scaling. Higher-mode unlock is stored but does not expose unsupported difficulty gameplay.','Opening text is extracted alongside ending; starting a new character still uses the existing village flow until opening is connected.'],'runtimeEndingComplete':True,'runtimeOpeningComplete':False,'fullNativeEquivalent':False}
(root/'reports/native-ending-source.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf8');print({'passed':True,'endingPages':stories['ending']['script'].count('#P '),'destination':rules['destination']})
